import boto3

def check_unsafe_content(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=text,
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    return False

if __name__ == '__main__':
    document_fields = ["This is a safe text.", "This text contains profanity and should be flagged."]
    for field in document_fields:
        if check_unsafe_content(field):
            print(f'Unsafe content detected in: {field}')
        else:
            print(f'Safe content: {field}')

from boto3 import client

dynamodb = client('dynamodb')

def create_request(table_name, item):
    return {
        'TableName': table_name,
        'Item': item
    }

def create_response(response):
    return response.get('Item', None)

def normalize_item(item):
    normalized_item = {}
    for key, value in item.items():
        if 'S' in value:
            normalized_item[key] = value['S']
        elif 'N' in value:
            normalized_item[key] = int(value['N'])
        elif 'BOOL' in value:
            normalized_item[key] = value['BOOL']
    return normalized_item

import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

DYNAMODB_REGION = 'us-west-2'
DYNAMODB_ACCESS_KEY = 'your_access_key'
DYNAMODB_SECRET_KEY = 'your_secret_key'

def create_dynamodb_client():
    try:
        session = boto3.Session(
            region_name=DYNAMODB_REGION,
            aws_access_key_id=DYNAMODB_ACCESS_KEY,
            aws_secret_access_key=DYNAMODB_SECRET_KEY
        )
        dynamodb_client = session.client('dynamodb')
        return dynamodb_client
    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f'Error creating DynamoDB client: {e}')
        return None

def list_tables(dynamodb_client):
    try:
        response = dynamodb_client.list_tables()
        return response['TableNames']
    except Exception as e:
        print(f'Error listing tables: {e}')
        return []

if __name__ == '__main__':
    dynamodb_client = create_dynamodb_client()
    if dynamodb_client:
        tables = list_tables(dynamodb_client)
        print('DynamoDB Tables:', tables)

import boto3

def fetch_document(table_name, document_id):
    dynamodb = boto3.client('dynamodb')
    response = dynamodb.get_item(
        TableName=table_name,
        Key={'id': {'S': document_id}}
    )
    return response.get('Item', None)

if __name__ == '__main__':
    table_name = 'YourTableName'
    document_id = 'YourDocumentId'
    document = fetch_document(table_name, document_id)
    print(document)
